begin;
create function pg_temp.assert_true(p_ok boolean,p_message text) returns void language plpgsql as $$begin if not coalesce(p_ok,false) then raise exception 'Assertion failed: %',p_message;end if;end$$;
create function pg_temp.expect_error(p_sql text,p_pattern text) returns void language plpgsql as $$begin begin execute p_sql;exception when others then if sqlerrm ilike '%'||p_pattern||'%' then return;end if;raise;end;raise exception 'Expected rejection: %',p_pattern;end$$;
insert into auth.users(id,email) values('a1000000-0000-0000-0000-000000000001','directorate@kafaa-test.invalid'),('a1000000-0000-0000-0000-000000000002','manager@kafaa-test.invalid'),('a1000000-0000-0000-0000-000000000003','viewer@kafaa-test.invalid');
insert into public.user_roles(user_id,role) values('a1000000-0000-0000-0000-000000000001','directorate'),('a1000000-0000-0000-0000-000000000003','viewer');
set local role authenticated;
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000001',true);
select public.save_center('a2000000-0000-0000-0000-000000000001',0,'{"code":" qa_one ","name_en":" One ","name_ar":"واحد","registered_patients":20,"dialysis_beds":10}');
select pg_temp.assert_true((select code='QA_ONE' and name_en='One' and created_by=auth.uid() and row_version=1 from public.centers where id='a2000000-0000-0000-0000-000000000001'),'Normalized persisted centre');
select public.save_center('a2000000-0000-0000-0000-000000000001',0,'{"code":"QA_ONE","name_en":"One","name_ar":"واحد","registered_patients":20,"dialysis_beds":10}');
select public.save_center('a2000000-0000-0000-0000-000000000001',1,'{"name_en":"Changed"}');
select pg_temp.expect_error($q$select public.save_center('a2000000-0000-0000-0000-000000000001',1,'{"name_en":"Stale"}')$q$,'KAFAA_CONFLICT');
select pg_temp.expect_error($q$select public.save_center('a2000000-0000-0000-0000-000000000002',0,'{"code":"qa_one","name_en":"Other","name_ar":"آخر"}')$q$,'duplicate');
select pg_temp.expect_error($q$select public.save_center('a2000000-0000-0000-0000-000000000001',2,'{"created_by":"a1000000-0000-0000-0000-000000000002"}')$q$,'Unsupported');
select pg_temp.expect_error($q$select public.save_center('a2000000-0000-0000-0000-000000000001',2,'{"registered_patients":-1}')$q$,'check constraint');
select public.set_center_active('a2000000-0000-0000-0000-000000000001',2,false);
select public.set_center_active('a2000000-0000-0000-0000-000000000001',3,true);
select pg_temp.expect_error($q$delete from public.centers where id='a2000000-0000-0000-0000-000000000001'$q$,'permission denied');
reset role;
select set_config('request.jwt.claim.sub','',true);
insert into public.user_roles(user_id,role,center_id) values('a1000000-0000-0000-0000-000000000002','center_manager','a2000000-0000-0000-0000-000000000001');
set local role authenticated;
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000002',true);
update public.centers set contact_phone='123',registered_patients=22 where id='a2000000-0000-0000-0000-000000000001';
select pg_temp.assert_true((select registered_patients=22 from public.centers where id='a2000000-0000-0000-0000-000000000001'),'Manager allowed fields');
select pg_temp.expect_error($q$update public.centers set name_en='Forged' where id='a2000000-0000-0000-0000-000000000001'$q$,'contact details');
select pg_temp.expect_error($q$update public.centers set is_active=false where id='a2000000-0000-0000-0000-000000000001'$q$,'contact details');
select pg_temp.expect_error($q$select public.save_center('a2000000-0000-0000-0000-000000000001',5,'{"name_en":"Forged"}')$q$,'ACCESS_DENIED');
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000003',true);
update public.centers set contact_phone='forged' where id='a2000000-0000-0000-0000-000000000001';
select pg_temp.assert_true((select contact_phone='123' from public.centers where id='a2000000-0000-0000-0000-000000000001'),'Viewer no write');
set local role anon;
select pg_temp.expect_error($q$select public.save_center('a2000000-0000-0000-0000-000000000001',5,'{}')$q$,'permission denied');
reset role;
rollback;
